class_name MeshIO
extends RefCounted
## Mesh files <-> plain triangles (metres, no GPU, no scene): OBJ and GLB in, GLB out. A mesh here is
## `verts` (PackedVector3Array) + `tris` (PackedInt32Array, 3 indices per triangle) in GODOT's winding
## (fronts clockwise, as StoneMesh keeps it: outward normal = -(b-a)x(c-a), see MeshCheck): OBJ and glTF are
## counter-clockwise, so the reader swaps two corners of every triangle and the writer swaps them back.
## Positions only: normals, UVs, colours and materials are dropped (the material decides the look).
## Every parse returns {verts, tris, error}; error is "" or a short message in Russian for the player (verts and
## tris are then empty). Nothing is checked for being closed here: MeshCheck.inspect does that.
## GLB goes through GLTFDocument.append_from_buffer (one synchronous engine call: cap the file, show «loading»
## one frame before) and reads the ImporterMesh arrays of GLTFState: generate_scene is never called, so nothing
## is uploaded to the GPU. Godot's glTF module has no Draco / meshopt decoder: such files are refused up front.
## The engine has no runtime OBJ loader: parse_obj is ours.

const MAX_OBJ_BYTES := 25 * 1024 * 1024
const MAX_GLB_BYTES := 10 * 1024 * 1024
const MAX_TRIS_WEB := 60000          # per mesh, browser build (single thread)
const MAX_TRIS_DESKTOP := 150000
const OBJ_CHUNK := 1 << 20           # an OBJ is decoded to text a megabyte of whole lines at a time (a String is 4 B/char)


static func max_tris() -> int:
	return MAX_TRIS_WEB if OS.has_feature("web") else MAX_TRIS_DESKTOP


static func _result(verts: PackedVector3Array, tris: PackedInt32Array, error := "") -> Dictionary:
	return {"verts": verts, "tris": tris, "error": error}


static func _fail(error: String) -> Dictionary:
	return _result(PackedVector3Array(), PackedInt32Array(), error)


## OBJ text (v, f; v/vt/vn forms, negative indices, n-gons fanned; o / g / usemtl / vt / vn / comments ignored).
## `cap` = most triangles allowed (0 = this platform's cap).
static func parse_obj(bytes: PackedByteArray, cap := 0) -> Dictionary:
	cap = cap if cap > 0 else max_tris()
	if bytes.size() > MAX_OBJ_BYTES:
		return _fail("Файл слишком большой (максимум %d МБ)." % (MAX_OBJ_BYTES >> 20))
	var verts := PackedVector3Array()
	var tris := PackedInt32Array()
	var pos := 0
	while pos < bytes.size():
		var end := mini(pos + OBJ_CHUNK, bytes.size())
		while end < bytes.size() and end > pos and bytes[end - 1] != 10:
			end -= 1                                   # cut at a line end (a UTF-8 character never straddles it)
		if end == pos:
			return _fail("Строка в OBJ длиннее мегабайта.")
		var err := _obj_lines(bytes.slice(pos, end).get_string_from_utf8().replace("\t", " "), verts, tris, cap)
		if err != "":
			return _fail(err)
		pos = end
	if tris.is_empty():
		return _fail("В файле нет граней.")
	return _result(verts, tris)


static func _obj_lines(text: String, verts: PackedVector3Array, tris: PackedInt32Array, cap: int) -> String:
	var ids := PackedInt32Array()
	for raw in text.split("\n", false):
		var line := raw.strip_edges()
		if line.begins_with("v "):
			var c := line.substr(2).split_floats(" ", false)
			if c.size() < 3:
				return "Вершина с менее чем тремя числами."
			verts.append(Vector3(c[0], c[1], c[2]))      # a 4th number (w) or colours are ignored
		elif line.begins_with("f "):
			var t := line.substr(2).split(" ", false)
			if t.size() < 3:
				return "Грань с менее чем тремя вершинами."
			ids.clear()
			for s in t:
				var i := s.get_slice("/", 0).to_int()      # "7", "7/2", "7//3", "7/2/3", "-1"
				i = i - 1 if i > 0 else (verts.size() + i if i < 0 else -1)
				if i < 0 or i >= verts.size():
					return "Грань ссылается на несуществующую вершину."
				ids.append(i)
			for k in range(1, ids.size() - 1):           # fan; a counter-clockwise OBJ face becomes clockwise
				tris.append(ids[0])
				tris.append(ids[k + 1])
				tris.append(ids[k])
			if tris.size() > cap * 3:
				return "Слишком много треугольников (максимум %d)." % cap
	return ""


