class_name MeshCheck
extends RefCounted
## Is a triangle soup a solid, and how much room does it take? For imported meshes (MeshIO) and every mesh that
## is charged by volume. Winding is Godot's (fronts clockwise: outward normal = -(b-a)x(c-a)), so a solid's
## signed volume is V = -sum a.(b x c) / 6 over its faces, positive when the faces point outward.
## Steps: weld vertices on a grid -> drop degenerate triangles -> refuse duplicate triangles -> edge census (every
## edge must be used by exactly two faces: an open edge is a hole, 3+ faces a pinch) -> walk the shells over shared
## edges, turning faces so each shell winds one way -> signed volume per shell in SCALAR DOUBLES from the shell's
## own first vertex (StoneMesh.volume keeps float32 cross products; this one does not) -> a shell with negative
## volume is turned inside out (no negative or cancelled charge) -> sum of |V|.
## Known limits: a real cavity (an inward shell inside another) is turned outward too and charged as a solid, and
## overlapping shells are charged twice (the game shows the number before it is spent). Vertices stay float32
## (PackedVector3Array): the volume is exact for the stored positions.

const WELD := 1e-5                    # grid pitch of the weld, m; vertices in one cell merge
const WELD_NEAR := 0.1                # a vertex within this share of a cell of the next cell is matched there too
const MIN_AREA2 := 4e-24              # |cross|^2 below this (area under 1e-12 m^2) is no triangle
const MIN_VOLUME := 1e-12


## Returns {ok, reason ("" or why the player is refused, Russian), closed, verts, tris (welded, clean, wound
## outward, grouped by shell), components, comps [{first, count, volume, inverted}] (first / count in triangles
## of `tris`; volume >= 0 after the turn-out; inverted = was negative), sum_abs_volume, volume (= the sum),
## aabb, welded (vertices merged away), degenerate_tris, duplicate_tris, boundary_edges, nonmanifold_edges,
## rewound_tris (faces turned to match their neighbours; shell turn-outs not counted)}.
static func inspect(verts: PackedVector3Array, tris: PackedInt32Array, tol := WELD) -> Dictionary:
	var out := {"ok": false, "reason": "", "closed": false, "verts": PackedVector3Array(), "tris": PackedInt32Array(),
		"components": 0, "comps": [], "sum_abs_volume": 0.0, "volume": 0.0, "aabb": AABB(), "welded": 0,
		"degenerate_tris": 0, "duplicate_tris": 0, "boundary_edges": 0, "nonmanifold_edges": 0, "rewound_tris": 0}
	if tris.size() < 3 or verts.is_empty():
		out.reason = "Модель пуста: нет ни одной грани."
		return out
	# 1. weld, drop degenerate faces, refuse duplicates
	var w := _weld(verts, tol)
	var ids: PackedInt32Array = w[0]
	var pos: PackedVector3Array = w[1]
	out.welded = verts.size() - pos.size()
	var t3 := PackedInt32Array()
	var seen := {}
	for t in tris.size() / 3:
		var a := ids[tris[t * 3]]
		var b := ids[tris[t * 3 + 1]]
		var c := ids[tris[t * 3 + 2]]
		if a == b or b == c or a == c or (pos[b] - pos[a]).cross(pos[c] - pos[a]).length_squared() < MIN_AREA2:
			out.degenerate_tris += 1
			continue
		var lo := mini(a, mini(b, c))
		var hi := maxi(a, maxi(b, c))
		var key​ := Vector3i(lo, a + b + c - lo - hi, hi)
		if seen.has(key​):
			out.duplicate_tris += 1
			continue
		seen[key​] = true
		t3.append_array([a, b, c])
	var tn := t3.size() / 3
	if out.duplicate_tris > 0:
		out.reason = "Повторяющиеся грани: %d." % out.duplicate_tris
		return out
	if tn == 0:
		out.reason = "Модель пуста: все грани вырождены."
		return out
	# 2. edge census: undirected edge -> id; the two half-edges of an edge point at each other (nbr)
	var nv := pos.size()
	var emap := {}
	var ecount := PackedInt32Array()
	var efirst := PackedInt32Array()
	var nbr := PackedInt32Array()
	nbr.resize(tn * 3)
	nbr.fill(-1)
	for h in tn * 3:
		var a := t3[h]
		var b := t3[h - 2 if h % 3 == 2 else h + 1]
		var key​ := mini(a, b) * nv + maxi(a, b)
		var e: int = emap.get(key​, -1)
		if e < 0:
			emap[key​] = ecount.size()
			ecount.append(1)
			efirst.append(h)
		else:
			ecount[e] += 1
			if ecount[e] == 2:
				nbr[h] = efirst[e]
				nbr[efirst[e]] = h
	for e in ecount:
		if e == 1:
			out.boundary_edges += 1
		elif e > 2:
			out.nonmanifold_edges += 1
	if out.boundary_edges > 0:
		out.reason = "Модель не замкнута: %d открытых рёбер (дыра)." % out.boundary_edges
		return out
	if out.nonmanifold_edges > 0:
		out.reason = "Рёбра, общие для трёх и более граней: %d (нужна цельная оболочка)." % out.nonmanifold_edges
		return out
	out.closed = true
