# ---- builders -------------------------------------------------------------------------------------------------

static func _quad(t: PackedInt32Array, a: int, b: int, c: int, d: int) -> void:       # (a b c d) counter-clockwise outward
	t.append_array([a, c, b, a, d, c])


static func _tri(t: PackedInt32Array, a: int, b: int, c: int) -> void:
	t.append_array([a, c, b])


static func _box(lo: Vector3, hi: Vector3) -> Dictionary:
	var v := PackedVector3Array()
	var t := PackedInt32Array()
	for i in 8:
		v.append(Vector3(hi.x if i & 1 != 0 else lo.x, hi.y if i & 2 != 0 else lo.y, hi.z if i & 4 != 0 else lo.z))
	for axis in 3:
		var u := (axis + 1) % 3
		var w := (axis + 2) % 3
		for side in 2:
			var c: Array = []
			for uv: Array in [[0, 0], [1, 0], [1, 1], [0, 1]]:     # u x w = +axis: counter-clockwise seen from +axis
				c.append((side << axis) | (int(uv[0]) << u) | (int(uv[1]) << w))
			if side == 0:
				c.reverse()
			_quad(t, c[0], c[1], c[2], c[3])
	return {"verts": v, "tris": t}


## UV sphere, `n` segments x `m` rings, poles are single vertices.
static func _sphere(r: float, n: int, m: int) -> Dictionary:
	var v := PackedVector3Array([Vector3(0, r, 0)])
	var t := PackedInt32Array()
	for i in range(1, m):
		var th := PI * i / m
		for j in n:
			var ph := TAU * j / n
			v.append(Vector3(r * sin(th) * cos(ph), r * cos(th), r * sin(th) * sin(ph)))
	v.append(Vector3(0, -r, 0))
	var ring := func(i: int, j: int) -> int: return 1 + (i - 1) * n + posmod(j, n)
	for j in n:
		_tri(t, 0, ring.call(1, j + 1), ring.call(1, j))
		_tri(t, v.size() - 1, ring.call(m - 1, j), ring.call(m - 1, j + 1))
		for i in range(1, m - 1):
			_quad(t, ring.call(i, j), ring.call(i, j + 1), ring.call(i + 1, j + 1), ring.call(i + 1, j))
	return {"verts": v, "tris": t}


static func _torus(big: float, small: float, n: int, m: int) -> Dictionary:
	var v := PackedVector3Array()
	var t := PackedInt32Array()
	for i in n:
		for j in m:
			var u := TAU * i / n
			var w := TAU * j / m
			v.append(Vector3((big + small * cos(w)) * cos(u), small * sin(w), (big + small * cos(w)) * sin(u)))
	var id := func(i: int, j: int) -> int: return posmod(i, n) * m + posmod(j, m)
	for i in n:
		for j in m:
			_quad(t, id.call(i, j), id.call(i, j + 1), id.call(i + 1, j + 1), id.call(i + 1, j))
	return {"verts": v, "tris": t}


static func _scaled(mesh: Dictionary, s: float) -> Dictionary:
	var v := PackedVector3Array()
	for p in (mesh.verts as PackedVector3Array):
		v.append(p * s)
	return {"verts": v, "tris": mesh.tris}


static func _reversed(tris: PackedInt32Array) -> PackedInt32Array:
	var r := tris.duplicate()
	for i in range(0, r.size() - 2, 3):
		var x := r[i + 1]
		r[i + 1] = r[i + 2]
		r[i + 2] = x
	return r


## Two meshes in one soup.
static func _join(a: Dictionary, b: Dictionary) -> Dictionary:
	var v: PackedVector3Array = (a.verts as PackedVector3Array).duplicate()
	var t: PackedInt32Array = (a.tris as PackedInt32Array).duplicate()
	var base := v.size()
	v.append_array(b.verts)
	for i in b.tris:
		t.append(base + i)
	return {"verts": v, "tris": t}


static func _obj_text(verts: PackedVector3Array, tris: PackedInt32Array) -> PackedByteArray:    # counter-clockwise, as OBJ files are
	var lines := PackedStringArray()
	for p in verts:
		lines.append("v %.9g %.9g %.9g" % [p.x, p.y, p.z])
	for i in range(0, tris.size() - 2, 3):
		lines.append("f %d %d %d" % [tris[i] + 1, tris[i + 2] + 1, tris[i + 1] + 1])
	return ("\n".join(lines) + "\n").to_utf8_buffer()


